alter table public.billing_credits add constraint billing_credits_amount_check CHECK ((amount > 0));
alter table public.billing_credits add constraint billing_credits_kind_check CHECK ((kind = ANY (ARRAY['free_month'::text, 'percent_off'::text])));
alter table public.booking_reminders add constraint booking_reminders_reminder_type_check CHECK ((reminder_type = ANY (ARRAY['confirmation'::text, '24h'::text, '2h'::text, 'review'::text])));
alter table public.bookings add constraint bookings_status_check CHECK ((status = ANY (ARRAY['confirmed'::text, 'cancelled'::text, 'completed'::text, 'no_show'::text])));
alter table public.client_sessions add constraint client_sessions_kind_check CHECK ((kind = ANY (ARRAY['session'::text, 'link'::text])));
alter table public.contacts add constraint contacts_notes_length CHECK (((notes IS NULL) OR (length(notes) <= 1000)));
alter table public.missed_calls_log add constraint missed_calls_log_status_check CHECK ((status = ANY (ARRAY['logged'::text, 'pending_reply'::text, 'sms_sent'::text, 'failed'::text])));
alter table public.referrals add constraint referrals_check CHECK ((referrer_user_id <> referred_user_id));
alter table public.referrals add constraint referrals_status_check CHECK ((status = ANY (ARRAY['signed_up'::text, 'qualified'::text])));
alter table public.sms_log add constraint sms_log_direction_check CHECK ((direction = ANY (ARRAY['outbound'::text, 'inbound'::text])));
alter table public.sms_log add constraint sms_log_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sent'::text, 'dev'::text, 'failed'::text, 'received'::text])));
alter table public.sticker_codes add constraint sticker_codes_status_check CHECK ((status = ANY (ARRAY['unclaimed'::text, 'active'::text, 'retired'::text])));
alter table public.users add constraint users_call_mode_check CHECK ((call_mode = ANY (ARRAY['forwarded'::text, 'direct'::text])));
alter table public.users add constraint users_carrier_check CHECK ((carrier = ANY (ARRAY['tmobile'::text, 'att'::text, 'verizon'::text, 'other'::text])));
alter table public.users add constraint users_loyalty_reward_cents_check CHECK (((loyalty_reward_cents >= 100) AND (loyalty_reward_cents <= 5000)));
alter table public.users add constraint users_missed_call_style_check CHECK ((missed_call_style = ANY (ARRAY['casual'::text, 'professional'::text, 'custom'::text])));
alter table public.users add constraint users_plan_check CHECK ((plan = ANY (ARRAY['basic'::text, 'full'::text])));
alter table public.users add constraint users_slug_format CHECK (((slug IS NULL) OR (slug ~ '^[a-z0-9](?:[a-z0-9-]{1,38}[a-z0-9])$'::text)));
alter table public.users add constraint users_theme_check CHECK ((theme = ANY (ARRAY['classic'::text, 'mint'::text, 'gold'::text, 'midnight'::text, 'cream'::text])));
alter table public.vip_clients add constraint vip_clients_language_supported CHECK ((client_language = ANY (ARRAY['en'::text, 'es'::text, 'pt'::text])));
alter table public.vip_clients add constraint vip_clients_optin_requires_proof CHECK (((is_opted_in = false) OR ((opted_in_at IS NOT NULL) AND (consent_text IS NOT NULL))));
alter table public.billing_credits add constraint billing_credits_referral_id_fkey FOREIGN KEY (referral_id) REFERENCES public.referrals(id) ON DELETE SET NULL;
alter table public.billing_credits add constraint billing_credits_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(user_id) ON DELETE CASCADE;
