alter table public.opt_outs add constraint opt_outs_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(user_id) ON DELETE CASCADE;
alter table public.phone_numbers add constraint phone_numbers_assigned_user_id_fkey FOREIGN KEY (assigned_user_id) REFERENCES public.users(user_id) ON DELETE SET NULL;
alter table public.referrals add constraint referrals_referred_user_id_fkey FOREIGN KEY (referred_user_id) REFERENCES public.users(user_id) ON DELETE CASCADE;
